import fitz

doc = fitz.open('/tmp/resume_姚泽平.pdf')
page = doc[0]

# 获取第一页文本，检查字体大小等详细信息
text_page = page.get_text("page")
blocks = page.get_text("blocks")
for b in blocks:
    if "lines" in b:
        for line in b["lines"]:
            for span in line["spans"]:
                if span["bbox"][1] > 210 and span["bbox"][1] < 300:
                    print(f"Y={span['bbox'][1]:.1f} | X={span['bbox'][0]:.1f}-{span['bbox'][2]:.1f} | size={span['size']:.2f} | font={span['font']} | color={span['color']} | text: {span['text']}")
